.libPaths(c('work/stage5_Rlib',.libPaths()));library(susieR);library(coloc)
base<-read.csv('outputs/stage6_rbm6_gnomad_aligned.csv');d<-read.csv('outputs/stage6_rbm6_brain_gnomad_aligned.csv');sel<-match(d$rs,base$rs);stopifnot(!anyNA(sel),!anyDuplicated(sel));p0<-nrow(base);p<-nrow(d);readR<-function(pop){M<-matrix(readBin(paste0('work/stage6_rbm6_gnomad_',pop,'_ld.bin'),'double',n=p0*p0,size=8,endian='little'),p0,p0);M<-M[sel,sel];dimnames(M)<-list(d$rs,d$rs);stopifnot(min(eigen(M,symmetric=TRUE,only.values=TRUE)$values)> -1e-8);M};Rn<-readR('nfe');Rf<-readR('fin')
traits<-c('RBM6_brain_n757','RBM6_brain_n983','Jansen_insomnia','FinnGen_HFRS','Mak_FI','Ye_FFS');ns<-c(757,983,313750,500737,402910,386565);fits<-list();diagnostics<-list();members<-list()
