write.csv(do.call(rbind,diagnostics),'outputs/stage6_rbm6_brain_gnomad_susie_diagnostics.csv',row.names=FALSE);if(length(members))write.csv(do.call(rbind,members),'outputs/stage6_rbm6_brain_gnomad_susie_members.csv',row.names=FALSE);saveRDS(fits,'work/stage6_rbm6_brain_gnomad_susie_fits.rds');out<-list()
